//! Chunk streaming: from "stored or generatable" to "on the client".
//!
//! One column goes through these stages:
//!
//! 1. [`ChunkLoader`](super::ChunkLoader) orders the player's view nearest
//!    first, shifted ahead in the direction the player moves.
//! 2. A column that is not in memory is read from storage by [`ColumnLoads`]
//!    on the async runtime, outside the tick and outside the generation pool,
//!    so stored terrain never waits behind generation. A storage miss is
//!    generated by the pool (expensive generators, in the order the tick asks
//!    for them) or right after the read (cheap generators). The finished column
//!    is encoded for the network on the same background thread.
//! 3. `stream_chunks` spawns the column and sends its `LevelChunk` (sub-chunk
//!    request mode) to every player that wants it, within each player's
//!    [`SendWindow`]. The client's `SubChunkRequest` acknowledges the column
//!    and is answered from the same encoding.
//!
//! The encoding ([`EncodedColumn`]) is made once per chunk revision and shared
//! by every player and every sub-chunk answer; an edited chunk is re-encoded
//! the next time it is sent or requested.

use std::collections::HashMap;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::time::{Duration, Instant};

use bevy_ecs::prelude::*;
use bytes::Bytes;
use jolyne::valentine::LevelChunkPacket;
use jolyne::valentine::types::{
    ChunkPos as WireChunkPos, DimensionType, EnumsSubChunkPacketPayloadHeightMapDataType,
    EnumsSubChunkPacketPayloadSubChunkRequestResult, SubChunkPacketPayloadHeightmapData,
    SubChunkPacketPayloadHeightmapDataRenderHeightMapType, SubChunkPacketPayloadSubChunkPacketData,
    SubChunkPacketPayloadSubChunkPosOffset,
};
use tokio::sync::mpsc;
use tracing::{debug, error, info, warn};

use super::generation_worker::ChunkGenerationWorker;
use super::manager::ChunkManager;
use crate::registry::block::BlockNetworkIds;
use crate::storage::{ChunkColumn, StorageError};
use crate::world::chunk::{ChunkRevision, HeightMapType, MIN_Y};
use crate::world::{Chunk, ChunkPos, SUBCHUNK_COUNT};

/// Lowest sub-chunk index of the column (`MIN_Y / 16`).
const LOWEST_SUBCHUNK: i32 = MIN_Y >> 4;

// =============================================================================
// Network encoding, once per chunk revision
// =============================================================================

/// A column's network encoding: the `LevelChunk` payload (biomes, sub-chunk
/// request mode) and every sub-chunk answer. Immutable and shared.
#[derive(Debug)]
pub struct EncodedColumn {
    revision: ChunkRevision,
    highest_subchunk: u16,
    biomes: Bytes,
    /// Indexed from the lowest sub-chunk up.
    subchunks: Vec<EncodedSubChunk>,
}

#[derive(Debug)]
struct EncodedSubChunk {
    /// `None` for an all-air section without block entities.
    payload: Option<Bytes>,
    height_map: SubChunkPacketPayloadHeightmapData,
}

impl EncodedColumn {
    /// Encode `chunk`'s current contents.
    pub fn encode(chunk: &Chunk, ids: BlockNetworkIds) -> Self {
        let subchunks = (0..i32::from(SUBCHUNK_COUNT))
            .map(|index| {
                let sub_y = LOWEST_SUBCHUNK + index;
                let empty =
                    chunk.is_subchunk_empty(sub_y) && !chunk.has_block_entities_in_subchunk(sub_y);
                let payload = (!empty)
                    .then(|| Bytes::from(chunk.encode_subchunk(sub_y, ids).unwrap_or_default()));
                EncodedSubChunk {
                    payload,
                    height_map: height_map_data(chunk.get_subchunk_heightmap(sub_y)),
                }
            })
            .collect();
        Self {
            revision: chunk.revision(),
            highest_subchunk: chunk.highest_subchunk(),
            biomes: Bytes::from(chunk.encode_biomes()),
            subchunks,
        }
    }

    /// Whether this is the encoding of `chunk`'s current contents.
    pub fn is_current(&self, chunk: &Chunk) -> bool {
        self.revision == chunk.revision()
    }

    /// Sub-chunks the client requests, counted from the bottom; 0 means it
    /// requests none.
    pub fn highest_subchunk(&self) -> u16 {
        self.highest_subchunk
    }

    /// The column's `LevelChunk` in sub-chunk request mode.
    pub fn level_chunk(&self, x: i32, z: i32, dimension: i32) -> LevelChunkPacket {
        LevelChunkPacket {
            chunk_position: WireChunkPos { x, z },
            dimension_id: DimensionType { value: dimension },
            subchunks_count: 0,
            client_request_sub_chunk_limit: Some(i32::from(self.highest_subchunk)),
            cache_enabled: false,
            cache_metadata: vec![],
            serialized_chunk_data: self.biomes.clone(),
        }
    }

    /// The answer for sub-chunk `sub_y`, or `None` outside the column.
    pub fn subchunk_entry(
        &self,
        sub_y: i32,
        offset: SubChunkPacketPayloadSubChunkPosOffset,
    ) -> Option<SubChunkPacketPayloadSubChunkPacketData> {
        let index = usize::try_from(sub_y - LOWEST_SUBCHUNK).ok()?;
        let sub = self.subchunks.get(index)?;
        Some(SubChunkPacketPayloadSubChunkPacketData {
            sub_chunk_pos_offset: offset,
            sub_chunk_request_result: if sub.payload.is_some() {
                EnumsSubChunkPacketPayloadSubChunkRequestResult::Success
            } else {
                EnumsSubChunkPacketPayloadSubChunkRequestResult::Successallair
            },
            serialized_sub_chunk: sub.payload.clone(),
            height_map_data: sub.height_map.clone(),
            blob_id: None,
        })
    }
}

fn height_map_data(
    (kind, map): (HeightMapType, Option<[u8; 256]>),
) -> SubChunkPacketPayloadHeightmapData {
    let (height_map_type, render_height_map_type) = match kind {
        HeightMapType::TooHigh => (
            EnumsSubChunkPacketPayloadHeightMapDataType::Alltoohigh,
            SubChunkPacketPayloadHeightmapDataRenderHeightMapType::Alltoohigh,
        ),
        HeightMapType::TooLow => (
            EnumsSubChunkPacketPayloadHeightMapDataType::Alltoolow,
            SubChunkPacketPayloadHeightmapDataRenderHeightMapType::Alltoolow,
        ),
        HeightMapType::HasData => (
            EnumsSubChunkPacketPayloadHeightMapDataType::Hasdata,
            SubChunkPacketPayloadHeightmapDataRenderHeightMapType::Hasdata,
        ),
    };
    let rows = map.map(|map| -> [Vec<i8>; 16] {
        std::array::from_fn(|z| (0..16).map(|x| map[(z << 4) | x] as i8).collect())
    });
    SubChunkPacketPayloadHeightmapData {
        height_map_type,
        subchunk_height_map: rows.clone(),
        render_height_map_type,
        subchunk_render_height_map: rows,
    }
}

/// The chunk's network encoding, kept with the chunk entity.
#[derive(Component, Debug, Default)]
pub struct ChunkNetCache(Option<Arc<EncodedColumn>>);

impl ChunkNetCache {
    pub fn new(encoded: Arc<EncodedColumn>) -> Self {
        Self(Some(encoded))
    }

    /// The encoding of `chunk`'s current contents; a chunk edited since it was
    /// encoded is encoded again here (on the calling thread).
    pub fn current(
        &mut self,
        chunk: &Chunk,
        ids: BlockNetworkIds,
        stats: &StreamStats,
    ) -> Arc<EncodedColumn> {
        if let Some(encoded) = &self.0
            && encoded.is_current(chunk)
        {
            return encoded.clone();
        }
        let started = Instant::now();
        let encoded = Arc::new(EncodedColumn::encode(chunk, ids));
        stats.reencoded.record(started.elapsed());
        self.0 = Some(encoded.clone());
        encoded
    }
}

// =============================================================================
// Send window: acknowledgement-clocked, no per-tick cap
// =============================================================================

/// How many columns a player may have been sent without having requested
/// their sub-chunks yet.
///
/// A column is acknowledged by the client's first `SubChunkRequest` for it,
/// which the client sends only once the `LevelChunk` reached it. Because every
/// packet shares one ordered channel, the window bounds the terrain queued
/// towards a client and adapts to how fast that client takes it: it grows by
/// one per acknowledgement that arrives within [`SendWindow::TARGET_ACK`]
/// (doubling every round trip, like slow start) and halves, at most once per
/// target interval, when acknowledgements arrive later. Columns that are never
/// acknowledged stop counting after [`SendWindow::ACK_TIMEOUT`].
#[derive(Debug)]
pub struct SendWindow {
    limit: usize,
    awaiting: HashMap<(i32, i32), Instant>,
    last_shrink: Option<Instant>,
}

impl Default for SendWindow {
    fn default() -> Self {
        Self {
            limit: Self::INITIAL,
            awaiting: HashMap::new(),
            last_shrink: None,
        }
    }
}

impl SendWindow {
    pub const INITIAL: usize = 128;
    pub const MIN: usize = 8;
    /// Keeps a tick's `LevelChunk`s plus sub-chunk answers well inside the
    /// session's 1024-packet outbound queue.
    pub const MAX: usize = 256;
    /// Acknowledgements later than this mean the client (or the link) is
    /// behind, and the window shrinks.
    pub const TARGET_ACK: Duration = Duration::from_millis(400);
    pub const ACK_TIMEOUT: Duration = Duration::from_secs(3);

    /// Current limit of unacknowledged columns.
    pub fn limit(&self) -> usize {
        self.limit
    }

    /// Columns sent and not yet acknowledged.
    pub fn in_flight(&self) -> usize {
        self.awaiting.len()
    }

    pub fn has_room(&self) -> bool {
        self.awaiting.len() < self.limit
    }

    /// A column was sent. Columns without sub-chunks are never requested and
    /// do not count.
    pub fn sent(&mut self, pos: (i32, i32), requests_subchunks: bool, now: Instant) {
        if requests_subchunks {
            self.awaiting.insert(pos, now);
        }
    }

    /// The client requested `pos`'s sub-chunks. Returns the acknowledgement
    /// delay for a column that was awaited.
    pub fn ack(&mut self, pos: (i32, i32), now: Instant) -> Option<Duration> {
        let sent = self.awaiting.remove(&pos)?;
        let delay = now.saturating_duration_since(sent);
        if delay <= Self::TARGET_ACK {
            self.limit = (self.limit + 1).min(Self::MAX);
        } else {
            self.shrink(now);
        }
        Some(delay)
    }

    /// Drops columns not acknowledged within [`Self::ACK_TIMEOUT`]; returns how many.
    pub fn expire(&mut self, now: Instant) -> usize {
        let before = self.awaiting.len();
        self.awaiting
            .retain(|_, sent| now.saturating_duration_since(*sent) < Self::ACK_TIMEOUT);
        before - self.awaiting.len()
    }

    /// The column left the view; it no longer counts.
    pub fn forget(&mut self, pos: (i32, i32)) {
        self.awaiting.remove(&pos);
    }

    fn shrink(&mut self, now: Instant) {
        if self
            .last_shrink
            .is_some_and(|last| now.saturating_duration_since(last) < Self::TARGET_ACK)
        {
            return;
        }
        self.last_shrink = Some(now);
        self.limit = (self.limit / 2).max(Self::MIN);
    }
}

// =============================================================================
// Background loads: storage reads, generation, encoding
// =============================================================================

/// Storage reads in flight at once. A stored column reads and decodes in a
/// few milliseconds on the blocking pool, but a finished read is only picked
/// up on the next tick, so this bounds stored columns per tick: 256 covers a
/// radius-12 view in three ticks without flooding the blocking pool.
pub const MAX_STORAGE_READS: usize = 256;

/// Generation requests kept in flight per pool worker. A worker finishes
/// about one chunk per tick, so three keep it busy until the next tick
/// refills the queue, while a moving player's new nearest chunks wait behind
/// at most three ticks of older requests.
pub const PENDING_GENERATIONS_PER_WORKER: usize = 3;

/// Outcome of one background load.
enum LoadEvent {
    Ready {
        pos: (i32, i32),
        column: Box<ChunkColumn>,
        encoded: Arc<EncodedColumn>,
        /// Loaded from storage (`false`: generated).
        stored: bool,
    },
    /// Storage has no such column; the generation pool must make it.
    Missing((i32, i32)),
    Failed((i32, i32), LoadFailure),
    /// An unloaded column was written, or comes back held after a failed write.
    Saved((i32, i32), Result<(), Box<HeldColumn>>),
}

/// Why a column could not be loaded. Either way nothing replaces it: a stored
/// column that can't be read is kept on disk untouched.
#[derive(Debug, thiserror::Error)]
pub enum LoadFailure {
    #[error(transparent)]
    Storage(#[from] StorageError),
    #[error("generation failed: {0}")]
    Generation(String),
    #[error("network encoding failed: {0}")]
    Encoding(String),
}

impl LoadFailure {
    /// Logs the failure for an operator.
    pub(crate) fn log(&self, (x, z): (i32, i32), dimension: i32) {
        match self {
            Self::Storage(error) => log_unloadable_column(x, z, dimension, error),
            Self::Generation(_) | Self::Encoding(_) => error!(
                chunk_x = x,
                chunk_z = z,
                dimension,
                error = %self,
                "Chunk column ({x}, {z}) in dimension {dimension} could not be loaded: {self}. \
                 Players see a gap there until they move away and back."
            ),
        }
    }
}

/// What an operator is told about a stored column that can't be loaded.
fn unloadable_column_message(
    x: i32,
    z: i32,
    dimension: i32,
    error: &impl std::fmt::Display,
) -> String {
    format!(
        "Chunk column ({x}, {z}) in dimension {dimension} can't be loaded from storage: {error}. \
         It is not generated or loaded; the stored column is kept on disk untouched, and \
         players see a gap there until it is repaired or removed."
    )
}

/// Log a stored column that can't be loaded.
fn log_unloadable_column(x: i32, z: i32, dimension: i32, error: &impl std::fmt::Display) {
    error!(
        chunk_x = x,
        chunk_z = z,
        dimension,
        %error,
        "{}",
        unloadable_column_message(x, z, dimension, error)
    );
}

/// An unloaded column whose background write failed. It comes back into the
/// world, edits and actors included, and its unload is retried later (see
/// [`ChunkPendingUnload::after_failed_save`](super::ChunkPendingUnload::after_failed_save)).
pub struct HeldColumn {
    pub pos: (i32, i32),
    pub column: ChunkColumn,
    /// Saves of this column that failed in a row, this one included.
    pub failed_saves: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LoadState {
    Reading,
    /// Not stored; waits for a generation slot.
    Missing,
    Generating,
    /// Unloaded and being written; read again only once the write is done.
    Saving,
}

/// A loaded column ready to become a chunk entity.
pub struct LoadedColumn {
    pub pos: (i32, i32),
    pub column: ChunkColumn,
    pub encoded: Arc<EncodedColumn>,
    pub stored: bool,
}

/// What [`ColumnLoads::drain`] collected this tick.
#[derive(Default)]
pub struct DrainedLoads {
    pub ready: Vec<LoadedColumn>,
    pub failed: Vec<(i32, i32)>,
    /// Unloaded columns whose write failed, to put back into the world.
    pub held: Vec<HeldColumn>,
}

/// Columns being read, waiting for generation, or generating.
#[derive(Resource)]
pub struct ColumnLoads {
    tx: mpsc::UnboundedSender<LoadEvent>,
    rx: mpsc::UnboundedReceiver<LoadEvent>,
    /// Load events received while waiting for a save, handled by the next drain.
    deferred: Vec<LoadEvent>,
    state: HashMap<(i32, i32), LoadState>,
    reads: usize,
    /// Pool generations in flight, also taken by storage reads that miss.
    generating: Arc<AtomicUsize>,
    saves: usize,
    /// Columns whose unload write failed, until the world takes them back.
    held: Vec<HeldColumn>,
}

impl Default for ColumnLoads {
    fn default() -> Self {
        let (tx, rx) = mpsc::unbounded_channel();
        Self {
            tx,
            rx,
            deferred: Vec::new(),
            state: HashMap::new(),
            reads: 0,
            generating: Arc::new(AtomicUsize::new(0)),
            saves: 0,
            held: Vec::new(),
        }
    }
}

impl ColumnLoads {
    pub fn state(&self, pos: (i32, i32)) -> Option<LoadState> {
        self.state.get(&pos).copied()
    }

    pub fn reads_in_flight(&self) -> usize {
        self.reads
    }

    pub fn generations_in_flight(&self) -> usize {
        self.generating.load(Ordering::Acquire)
    }

    /// Unloaded columns still being written.
    pub fn saves_in_flight(&self) -> usize {
        self.saves
    }

    /// Whether every load and save has finished.
    pub fn is_idle(&self) -> bool {
        self.reads == 0 && self.generations_in_flight() == 0 && self.saves == 0
    }

    /// Collects finished loads (non-blocking); failures are logged for
    /// `dimension`.
    pub fn drain(&mut self, dimension: i32) -> DrainedLoads {
        let mut drained = DrainedLoads::default();
        let deferred = std::mem::take(&mut self.deferred);
        let received = std::iter::from_fn(|| self.rx.try_recv().ok()).collect::<Vec<_>>();
        for event in deferred.into_iter().chain(received) {
            match event {
                LoadEvent::Ready {
                    pos,
                    column,
                    encoded,
                    stored,
                } => {
                    self.finish(pos);
                    drained.ready.push(LoadedColumn {
                        pos,
                        column: *column,
                        encoded,
                        stored,
                    });
                }
                LoadEvent::Missing(pos) => {
                    self.reads -= 1;
                    self.state.insert(pos, LoadState::Missing);
                }
                LoadEvent::Failed(pos, failure) => {
                    failure.log(pos, dimension);
                    self.finish(pos);
                    drained.failed.push(pos);
                }
                LoadEvent::Saved(pos, result) => self.saved(pos, result),
            }
        }
        drained.held = self.take_held();
        drained
    }

    fn finish(&mut self, pos: (i32, i32)) {
        match self.state.remove(&pos) {
            Some(LoadState::Reading) => self.reads -= 1,
            Some(LoadState::Saving) => self.saves -= 1,
            Some(LoadState::Generating | LoadState::Missing) | None => {}
        }
    }

    /// Writes an unloaded column in the background; `pos` is not read again
    /// until the write finished, so a returning player gets what was saved.
    /// `failed_saves` counts this column's earlier writes that failed in a
    /// row; a failed write hands the column back (see [`HeldColumn`]).
    pub fn start_save(
        &mut self,
        pos: (i32, i32),
        column: ChunkColumn,
        failed_saves: u32,
        manager: &ChunkManager,
    ) {
        let Some(provider) = manager.provider() else {
            return;
        };
        let dimension = manager.dimension();
        let tx = self.tx.clone();
        self.state.insert(pos, LoadState::Saving);
        self.saves += 1;
        spawn_job(manager.runtime(), async move {
            let result = provider
                .save_column(ChunkPos::new(pos.0, pos.1), dimension, &column)
                .await;
            let result = result.map_err(|error| {
                debug!(
                    chunk = ?pos,
                    %error,
                    failed_saves = failed_saves + 1,
                    "Failed to save chunk before unload; keeping it loaded"
                );
                Box::new(HeldColumn {
                    pos,
                    column,
                    failed_saves: failed_saves.saturating_add(1),
                })
            });
            let _ = tx.send(LoadEvent::Saved(pos, result));
        });
    }

    fn saved(&mut self, pos: (i32, i32), result: Result<(), Box<HeldColumn>>) {
        self.finish(pos);
        if let Err(held) = result {
            self.held.push(*held);
        }
    }

    /// Columns whose unload write failed, for the world to take back.
    pub fn take_held(&mut self) -> Vec<HeldColumn> {
        std::mem::take(&mut self.held)
    }

    /// Takes back `pos` if its unload write failed.
    pub fn take_held_at(&mut self, pos: (i32, i32)) -> Option<HeldColumn> {
        let index = self.held.iter().position(|held| held.pos == pos)?;
        Some(self.held.swap_remove(index))
    }

    /// Blocks until `pos` is not being saved, for code that reads storage
    /// synchronously. Other finished loads wait for the next [`Self::drain`].
    pub fn wait_for_save(&mut self, pos: (i32, i32)) {
        while self.state(pos) == Some(LoadState::Saving) && self.receive_save_blocking() {}
    }

    /// Blocks until no unload write is in flight (see [`Self::wait_for_save`]).
    pub fn wait_for_saves(&mut self) {
        while self.saves > 0 && self.receive_save_blocking() {}
    }

    /// Handles the next event, keeping any but a finished save for the next
    /// [`Self::drain`]; sleeps briefly when none arrived. `false` once no
    /// event can arrive any more.
    fn receive_save_blocking(&mut self) -> bool {
        match self.rx.try_recv() {
            Ok(LoadEvent::Saved(saved, result)) => self.saved(saved, result),
            Ok(other) => self.deferred.push(other),
            Err(mpsc::error::TryRecvError::Empty) => std::thread::sleep(Duration::from_millis(1)),
            Err(mpsc::error::TryRecvError::Disconnected) => return false,
        }
        true
    }

    /// Waits until every unload save finished (server shutdown).
    pub async fn finish_saves(&mut self) {
        while self.saves > 0 {
            match self.rx.recv().await {
                Some(LoadEvent::Saved(pos, result)) => self.saved(pos, result),
                Some(other) => self.deferred.push(other),
                None => return,
            }
        }
    }

    /// Forgets storage misses no player wants any more.
    pub fn retain_missing(&mut self, mut wanted: impl FnMut((i32, i32)) -> bool) {
        self.state
            .retain(|&pos, state| *state != LoadState::Missing || wanted(pos));
    }

    /// Starts reading `pos` from storage. The manager must have a provider.
    ///
    /// A storage miss is generated right away: inline for cheap generators,
    /// or by the pool when a generation slot is free (a fresh world then
    /// starts generating without waiting a tick). Otherwise the column is
    /// reported [`LoadState::Missing`] and the tick asks for it in priority
    /// order once slots free up.
    pub fn start_read(
        &mut self,
        pos: (i32, i32),
        manager: &ChunkManager,
        ids: BlockNetworkIds,
        stats: &StreamStats,
    ) {
        let provider = manager
            .provider()
            .expect("storage reads need a world provider");
        let on_miss = match manager.generation_pool() {
            Some(pool) => OnMiss::Pool {
                pool,
                slots: self.generating.clone(),
                cap: manager.generation_threads() * PENDING_GENERATIONS_PER_WORKER,
                dimension: manager.dimension(),
            },
            None => OnMiss::Inline {
                pipeline: manager.pipeline().clone(),
                bounds: manager.world_config().bounds,
            },
        };
        let dimension = manager.dimension();
        let tx = self.tx.clone();
        let stats = stats.clone();
        self.state.insert(pos, LoadState::Reading);
        self.reads += 1;
        spawn_job(manager.runtime(), async move {
            let started = Instant::now();
            let event = match provider
                .load_column(ChunkPos::new(pos.0, pos.1), dimension)
                .await
            {
                Ok(Some(column)) => {
                    stats.read.record(started.elapsed());
                    ready(pos, column, true, ids, stats).await
                }
                Ok(None) => {
                    stats.missed.record(started.elapsed());
                    on_miss.generate(pos, ids, stats).await
                }
                Err(error) => LoadEvent::Failed(pos, error.into()),
            };
            let _ = tx.send(event);
        });
    }

    /// Asks the generation pool for `pos`. Returns `false` when the pool is
    /// unavailable.
    pub fn start_generation(
        &mut self,
        pos: (i32, i32),
        manager: &ChunkManager,
        ids: BlockNetworkIds,
        stats: &StreamStats,
    ) -> bool {
        let Some(pool) = manager.generation_pool() else {
            warn!(chunk = ?pos, "Chunk generation pool is unavailable");
            return false;
        };
        let Some(receiver) = pool.generate(pos.0, pos.1, None, manager.dimension()) else {
            warn!(chunk = ?pos, "Chunk generation pool is unavailable");
            return false;
        };
        let tx = self.tx.clone();
        let stats = stats.clone();
        let slots = self.generating.clone();
        slots.fetch_add(1, Ordering::AcqRel);
        self.state.insert(pos, LoadState::Generating);
        spawn_job(manager.runtime(), async move {
            let event = pool_column(pos, receiver, &slots, ids, stats).await;
            let _ = tx.send(event);
        });
        true
    }
}

/// What a storage read does when the column is not stored.
enum OnMiss {
    Inline {
        pipeline: Arc<crate::world::generator::ChunkPipeline>,
        bounds: crate::world::WorldBounds,
    },
    Pool {
        pool: ChunkGenerationWorker,
        slots: Arc<AtomicUsize>,
        cap: usize,
        dimension: i32,
    },
}

impl OnMiss {
    async fn generate(
        self,
        pos: (i32, i32),
        ids: BlockNetworkIds,
        stats: StreamStats,
    ) -> LoadEvent {
        match self {
            Self::Inline { pipeline, bounds } => {
                let started = Instant::now();
                match tokio::task::spawn_blocking(move || generate_inline(&pipeline, bounds, pos))
                    .await
                {
                    Ok(Ok(column)) => {
                        stats.generated.record(started.elapsed());
                        ready(pos, column, false, ids, stats).await
                    }
                    Ok(Err(failure)) => LoadEvent::Failed(pos, failure),
                    Err(error) => {
                        LoadEvent::Failed(pos, LoadFailure::Generation(error.to_string()))
                    }
                }
            }
            Self::Pool {
                pool,
                slots,
                cap,
                dimension,
            } => {
                let reserved = slots
                    .fetch_update(Ordering::AcqRel, Ordering::Acquire, |n| {
                        (n < cap).then_some(n + 1)
                    })
                    .is_ok();
                if !reserved {
                    return LoadEvent::Missing(pos);
                }
                let Some(receiver) = pool.generate(pos.0, pos.1, None, dimension) else {
                    slots.fetch_sub(1, Ordering::AcqRel);
                    return LoadEvent::Failed(
                        pos,
                        LoadFailure::Generation("the generation pool shut down".into()),
                    );
                };
                pool_column(pos, receiver, &slots, ids, stats).await
            }
        }
    }
}

/// Waits for a pool generation, frees its slot, and encodes the column.
async fn pool_column(
    pos: (i32, i32),
    receiver: tokio::sync::oneshot::Receiver<super::generation_worker::ChunkLoadResult>,
    slots: &AtomicUsize,
    ids: BlockNetworkIds,
    stats: StreamStats,
) -> LoadEvent {
    let started = Instant::now();
    let result = receiver.await;
    slots.fetch_sub(1, Ordering::AcqRel);
    match result {
        Ok(Ok((column, stored))) => {
            stats.generated.record(started.elapsed());
            ready(pos, column, stored, ids, stats).await
        }
        Ok(Err(error)) => LoadEvent::Failed(pos, LoadFailure::Generation(error.to_string())),
        Err(_) => LoadEvent::Failed(
            pos,
            LoadFailure::Generation("the generation pool dropped the request".into()),
        ),
    }
}

/// Generates `pos` with a cheap generator (all air outside the world bounds).
pub(crate) fn generate_inline(
    pipeline: &crate::world::generator::ChunkPipeline,
    bounds: crate::world::WorldBounds,
    pos: (i32, i32),
) -> Result<ChunkColumn, LoadFailure> {
    pipeline
        .generate_within(bounds, ChunkPos::new(pos.0, pos.1))
        .map(ChunkColumn::new)
        .map_err(|error| LoadFailure::Generation(error.to_string()))
}

/// Encodes `column` on the blocking pool and wraps it as a finished load.
async fn ready(
    pos: (i32, i32),
    column: ChunkColumn,
    stored: bool,
    ids: BlockNetworkIds,
    stats: StreamStats,
) -> LoadEvent {
    let encoded = tokio::task::spawn_blocking(move || {
        let started = Instant::now();
        let encoded = EncodedColumn::encode(&column.chunk, ids);
        stats.encoded.record(started.elapsed());
        (column, encoded)
    })
    .await;
    match encoded {
        Ok((column, encoded)) => LoadEvent::Ready {
            pos,
            column: Box::new(column),
            encoded: Arc::new(encoded),
            stored,
        },
        Err(error) => LoadEvent::Failed(pos, LoadFailure::Encoding(error.to_string())),
    }
}

/// Runs a load on the server's runtime, or on a private one on a helper
/// thread when the world lives outside any runtime (tools and tests).
fn spawn_job(
    runtime: Option<&tokio::runtime::Handle>,
    job: impl Future<Output = ()> + Send + 'static,
) {
    match runtime {
        Some(handle) => {
            handle.spawn(job);
        }
        None => {
            std::thread::spawn(move || {
                tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .expect("chunk load runtime")
                    .block_on(job)
            });
        }
    }
}

// =============================================================================
// Stage statistics
// =============================================================================

/// Count and total time of one streaming stage.
#[derive(Debug, Default)]
pub struct StageStat {
    count: AtomicU64,
    micros: AtomicU64,
}

impl StageStat {
    pub fn record(&self, elapsed: Duration) {
        self.record_many(1, elapsed);
    }

    /// `count` items that together took `elapsed`.
    pub fn record_many(&self, count: u64, elapsed: Duration) {
        self.count.fetch_add(count, Ordering::Relaxed);
        self.micros
            .fetch_add(elapsed.as_micros() as u64, Ordering::Relaxed);
    }

    pub fn count(&self) -> u64 {
        self.count.load(Ordering::Relaxed)
    }

    fn take(&self) -> (u64, f64) {
        let count = self.count.swap(0, Ordering::Relaxed);
        let micros = self.micros.swap(0, Ordering::Relaxed);
        let mean_ms = if count == 0 {
            0.0
        } else {
            micros as f64 / count as f64 / 1e3
        };
        (count, mean_ms)
    }
}

/// Per-stage counts and mean times of chunk streaming, shared with the
/// background loads and logged (`unastar::stream`, info) every second
/// while terrain moves.
#[derive(Resource, Clone, Default)]
pub struct StreamStats(Arc<StreamStatsInner>);

#[derive(Debug, Default)]
pub struct StreamStatsInner {
    /// Storage reads that found the column (read and decode).
    pub read: StageStat,
    /// Storage reads that found nothing.
    pub missed: StageStat,
    /// Generation: request to finished column.
    pub generated: StageStat,
    /// Background network encoding of a loaded column.
    pub encoded: StageStat,
    /// Re-encoding an edited chunk on the tick thread.
    pub reencoded: StageStat,
    /// `LevelChunk`s sent, with the tick time spent sending them.
    pub sent: StageStat,
    /// Sub-chunk requests answered, with the tick time spent answering.
    pub answered: StageStat,
    /// `LevelChunk` to the client's first `SubChunkRequest` for it.
    pub acked: StageStat,
    /// Columns never acknowledged within the window timeout.
    pub unacked: AtomicU64,
}

impl std::ops::Deref for StreamStats {
    type Target = StreamStatsInner;
    fn deref(&self) -> &StreamStatsInner {
        &self.0
    }
}

/// Ticks between two streaming summaries.
const STATS_INTERVAL_TICKS: u32 = 20;

/// System: logs and resets the streaming statistics every
/// [`STATS_INTERVAL_TICKS`], when anything was streamed.
pub fn log_stream_stats(stats: Res<StreamStats>, mut ticks: Local<u32>) {
    *ticks += 1;
    if *ticks < STATS_INTERVAL_TICKS {
        return;
    }
    *ticks = 0;
    if stats.sent.count() == 0 && stats.answered.count() == 0 && stats.generated.count() == 0 {
        return;
    }
    let (read, read_ms) = stats.read.take();
    let (missed, missed_ms) = stats.missed.take();
    let (generated, generated_ms) = stats.generated.take();
    let (encoded, encoded_ms) = stats.encoded.take();
    let (reencoded, reencoded_ms) = stats.reencoded.take();
    let (sent, sent_ms) = stats.sent.take();
    let (answered, answered_ms) = stats.answered.take();
    let (acked, acked_ms) = stats.acked.take();
    let unacked = stats.unacked.swap(0, Ordering::Relaxed);
    info!(
        target: "unastar::stream",
        read, read_ms, missed, missed_ms, generated, generated_ms, encoded, encoded_ms,
        reencoded, reencoded_ms, sent, sent_ms, answered, answered_ms, acked, acked_ms, unacked,
        "chunk streaming (counts and mean ms over the last second)"
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::world::chunk::blocks;

    #[test]
    fn an_unloadable_column_message_names_it_and_says_it_is_kept() {
        let message = unloadable_column_message(
            -3,
            7,
            1,
            &StorageError::Deserialization("subchunk y=2: bad".into()),
        );
        assert_eq!(
            message,
            "Chunk column (-3, 7) in dimension 1 can't be loaded from storage: \
             Deserialization error: subchunk y=2: bad. It is not generated or loaded; \
             the stored column is kept on disk untouched, and players see a gap there \
             until it is repaired or removed."
        );
    }

    fn ms(n: u64) -> Duration {
        Duration::from_millis(n)
    }

    #[test]
    fn window_admits_up_to_its_limit_and_ignores_columns_without_subchunks() {
        let now = Instant::now();
        let mut window = SendWindow::default();
        for i in 0..SendWindow::INITIAL as i32 {
            assert!(window.has_room());
            window.sent((i, 0), true, now);
        }
        assert!(!window.has_room());
        // All-air columns are never requested, so they never block the window.
        window.sent((99, 99), false, now);
        assert_eq!(window.in_flight(), SendWindow::INITIAL);
    }

    #[test]
    fn prompt_acks_grow_the_window_by_one_each_up_to_the_max() {
        let start = Instant::now();
        let mut window = SendWindow::default();
        for i in 0..2000 {
            window.sent((i, 0), true, start);
            assert_eq!(window.ack((i, 0), start + ms(10)), Some(ms(10)));
        }
        assert_eq!(window.limit(), SendWindow::MAX);
        // An unknown column is no acknowledgement.
        assert_eq!(window.ack((-1, -1), start), None);
        assert_eq!(window.limit(), SendWindow::MAX);
    }

    #[test]
    fn late_acks_halve_the_window_once_per_interval_and_never_below_min() {
        let start = Instant::now();
        let late = SendWindow::TARGET_ACK + ms(1);
        let mut window = SendWindow::default();
        for i in 0..12 {
            window.sent((i, 0), true, start);
        }
        window.ack((0, 0), start + late);
        assert_eq!(window.limit(), SendWindow::INITIAL / 2);
        // A second late ack in the same interval is the same congestion.
        window.ack((1, 0), start + late + ms(1));
        assert_eq!(window.limit(), SendWindow::INITIAL / 2);
        // One interval later it halves again; repeated, it bottoms out.
        let mut t = start + late;
        t += SendWindow::TARGET_ACK;
        window.ack((2, 0), t);
        assert_eq!(window.limit(), SendWindow::INITIAL / 4);
        for i in 3..12 {
            t += SendWindow::TARGET_ACK;
            window.ack((i, 0), t);
        }
        assert_eq!(window.limit(), SendWindow::MIN);
        for i in 10..20 {
            t += SendWindow::TARGET_ACK;
            window.sent((i, 0), true, start);
            window.ack((i, 0), t);
        }
        assert_eq!(window.limit(), SendWindow::MIN);
    }

    #[test]
    fn unacknowledged_columns_stop_counting_after_the_timeout() {
        let start = Instant::now();
        let mut window = SendWindow::default();
        window.sent((0, 0), true, start);
        window.sent((1, 0), true, start + ms(500));
        assert_eq!(window.expire(start + SendWindow::ACK_TIMEOUT - ms(1)), 0);
        assert_eq!(window.expire(start + SendWindow::ACK_TIMEOUT), 1);
        assert_eq!(window.in_flight(), 1);
        window.forget((1, 0));
        assert_eq!(window.in_flight(), 0);
    }

    fn sample_chunk() -> Chunk {
        let mut chunk = Chunk::new(3, -7);
        chunk.fill_floor(5, *blocks::STONE);
        chunk.set_block(4, 70, 9, *blocks::DIAMOND_ORE);
        chunk
    }

    #[test]
    fn encoding_matches_the_chunk_section_by_section() {
        let chunk = sample_chunk();
        let ids = BlockNetworkIds::Hashed;
        let encoded = EncodedColumn::encode(&chunk, ids);
        assert!(encoded.is_current(&chunk));
        assert_eq!(encoded.highest_subchunk(), chunk.highest_subchunk());
        let packet = encoded.level_chunk(3, -7, 0);
        assert_eq!(packet.serialized_chunk_data.as_ref(), chunk.encode_biomes());
        for sub_y in LOWEST_SUBCHUNK..LOWEST_SUBCHUNK + i32::from(SUBCHUNK_COUNT) {
            let entry = encoded
                .subchunk_entry(sub_y, SubChunkPacketPayloadSubChunkPosOffset::default())
                .unwrap();
            if chunk.is_subchunk_empty(sub_y) {
                assert_eq!(
                    entry.sub_chunk_request_result,
                    EnumsSubChunkPacketPayloadSubChunkRequestResult::Successallair
                );
                assert!(entry.serialized_sub_chunk.is_none());
            } else {
                assert_eq!(
                    entry.sub_chunk_request_result,
                    EnumsSubChunkPacketPayloadSubChunkRequestResult::Success
                );
                assert_eq!(
                    entry.serialized_sub_chunk.as_deref(),
                    chunk.encode_subchunk(sub_y, ids).as_deref()
                );
            }
        }
        assert!(
            encoded
                .subchunk_entry(LOWEST_SUBCHUNK - 1, Default::default())
                .is_none()
        );
    }

    #[test]
    fn the_cache_reencodes_only_an_edited_chunk() {
        let stats = StreamStats::default();
        let ids = BlockNetworkIds::Hashed;
        let mut chunk = sample_chunk();
        let mut cache = ChunkNetCache::new(Arc::new(EncodedColumn::encode(&chunk, ids)));
        let first = cache.current(&chunk, ids, &stats);
        assert!(Arc::ptr_eq(&first, &cache.current(&chunk, ids, &stats)));
        assert_eq!(stats.reencoded.count(), 0);

        chunk.set_block(4, 70, 9, *blocks::AIR);
        let edited = cache.current(&chunk, ids, &stats);
        assert!(!Arc::ptr_eq(&first, &edited));
        assert_eq!(stats.reencoded.count(), 1);
        let sub_y = 70 >> 4;
        assert_eq!(
            edited
                .subchunk_entry(sub_y, Default::default())
                .unwrap()
                .serialized_sub_chunk
                .as_deref(),
            chunk.encode_subchunk(sub_y, ids).as_deref()
        );
    }

    #[test]
    fn a_clone_edited_apart_never_shares_the_original_revision() {
        let mut original = sample_chunk();
        let mut copy = original.clone();
        assert_ne!(original.revision(), copy.revision());
        original.set_block(0, 0, 0, *blocks::STONE);
        copy.set_block(1, 0, 0, *blocks::STONE);
        assert_ne!(original.revision(), copy.revision());
    }
}
